solution.octal.zig:
pub fn toDecimal(s: []const u8) u64 {
    var n: u64 = 0;
    for (s) |c| {
        if (c < '0' or c >= '0' + 8) return 0;
        n = n * 8 + c - '0';
    }
    return n;
}

