// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("octal.zig");
test "conversion and invalid digits" {
    try t.expectEqual(@as(u64, 155), m.toDecimal("233"));
    try t.expectEqual(@as(u64, 0), m.toDecimal("8"));
    try t.expectEqual(@as(u64, 0), m.toDecimal("-1"));
    try t.expectEqual(@as(u64, 0), m.toDecimal(""));
    try t.expectEqual(@as(u64, 8), m.toDecimal("0010"));
}
test "python test_octal_1_is_decimal_1" {
    try t.expectEqual(@as(u64, 1), m.toDecimal("1"));
}
test "python test_octal_10_is_decimal_8" {
    try t.expectEqual(@as(u64, 8), m.toDecimal("10"));
}
test "python test_octal_17_is_decimal_15" {
    try t.expectEqual(@as(u64, 15), m.toDecimal("17"));
}
test "python test_octal_130_is_decimal_88" {
    try t.expectEqual(@as(u64, 88), m.toDecimal("130"));
}
test "python test_octal_2047_is_decimal_1063" {
    try t.expectEqual(@as(u64, 1063), m.toDecimal("2047"));
}
test "python test_octal_1234567_is_decimal_342391" {
    try t.expectEqual(@as(u64, 342391), m.toDecimal("1234567"));
}
test "python test_valid_octal_formatted_string_011_is_decimal_9" {
